credito_pd = ruido(credito_pd, 'Monto', 'Monto_ruido', 50_000, 0.25)
credito_pd['Monto_ruido_cat'] = pd.cut(credito_pd['Monto_ruido'], bins=cut_bins, labels=categorias_monto)


